namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "Your build completed successfully.",
        "New comment on pull request #42.",
        "Deployment to staging finished.",
        "Alert: CPU usage exceeded 90%.",
        "User 'admin' logged in from a new device.",
        "Backup completed for database 'orders'.",
        "Scheduled maintenance window starts in 1 hour.",
        "New team member joined the project.",
    ];

    public Task<List<Notification>> GetInitialNotificationsAsync()
    {
        lock (_lock)
        {
            var notifications = new List<Notification>();
            for (var i = 0; i < 3; i++)
            {
                notifications.Add(CreateNotification());
            }
            return Task.FromResult(notifications);
        }
    }

    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        lock (_lock)
        {
            // Simulate: roughly 50% chance a new notification appears each poll
            if (Random.Shared.NextDouble() < 0.5)
            {
                return Task.FromResult(new List<Notification> { CreateNotification() });
            }
            return Task.FromResult(new List<Notification>());
        }
    }

    private Notification CreateNotification()
    {
        var id = _nextId++;
        var message = _templates[Random.Shared.Next(_templates.Length)];
        return new Notification(id, message, DateTime.UtcNow);
    }
}

